                              const double *x, double *y, int n) {
    int i = 0;
    for (; i + 1 < n; i += 2) {
        int s0 = indptr[i], e0 = indptr[i + 1];
        int s1 = e0, e1 = indptr[i + 2];
        double a0 = 0.0, a1 = 0.0;
        int j = s0;
        for (; j < e0; j++) a0 += data[j] * x[indices[j]];
        for (j = s1; j < e1; j++) a1 += data[j] * x[indices[j]];
        y[i] = a0;
        y[i + 1] = a1;
    }
    for (; i < n; i++) {
        double s = 0.0;
        for (int j = indptr[i]; j < indptr[i + 1]; j++)
            s += data[j] * x[indices[j]];
        y[i] = s;
    }
}

