static void csr_matvec(const int *indptr, const int *indices, const double *data,
                       const double *x, double *y, int n) {
    for (int i = 0; i < n; ++i) {
        const int start = indptr[i];
        const int end = indptr[i + 1];
        double s = 0.0;
        int j = start;
        for (; j + 3 < end; j += 4) {
            s += data[j] * x[indices[j]];
            s += data[j + 1] * x[indices[j + 1]];
            s += data[j + 2] * x[indices[j + 2]];
            s += data[j + 3] * x[indices[j + 3]];
        }
        for (; j < end; ++j) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

int ar_eigs_loop(void *fn, State *state,
                 double *resid, double *v, int *ipntr,
                 double *workd, double *workl,
                 const int *indptr, const int *indices, const double *data) {
    dnaupd_fn dnaupd = (dnaupd_fn)fn;
    const int n = state->n;
    int guard = 0;
    for (;;) {
        dnaupd(state, resid, v, n, ipntr, workd, workl);
        const int ido = state->ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            csr_matvec(indptr, indices, data, workd + ipntr[0], workd + ipntr[1], n);
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
        if (++guard > 8000000) {
            state->info = -999;
            break;
        }
    }
    return state->info;
}
